INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7043084, 1069952, 81362, '<td valign="top">Subdued mood, but strong echoes of classic still life paintings. Lots to look at.</td>', 'Subdued mood, but strong echoes of classic still life paintings. Lots to look at.', '2013-05-25 17:25:05.000000', NULL, 1),
(7043085, 1070006, 81362, '<td valign="top">Diagonal composition works well with this subject. Tangle of tendrils gives us many curved lines to lead the eye around.</td>', 'Diagonal composition works well with this subject. Tangle of tendrils gives us many curved lines to lead the eye around.', '2013-05-25 17:26:27.000000', NULL, 1),
(7043086, 1069795, 81362, '<td valign="top">The sparkles give this a party atmosphere.</td>', 'The sparkles give this a party atmosphere.', '2013-05-25 17:27:25.000000', NULL, 1),
(7043087, 1069809, 81362, '<td valign="top">Fits the topic well.</td>', 'Fits the topic well.', '2013-05-25 17:28:37.000000', NULL, 1),
(7043088, 1070016, 81362, '<td valign="top">The tips look like yawning faces. Nice job of filling the frame and capturing a repeating pattern with just enough variation to maintain interest.</td>', 'The tips look like yawning faces. Nice job of filling the frame and capturing a repeating pattern with just enough variation to maintain interest.', '2013-05-25 17:29:59.000000', NULL, 1),
(7043089, 1069616, 136989, '<td valign="top">My favorite in this challenge.  I am always a sucker for how gray skies and fog make greens pop.  Makes me want to go for a hike...</td>', 'My favorite in this challenge.  I am always a sucker for how gray skies and fog make greens pop.  Makes me want to go for a hike...', '2013-05-25 17:30:36.000000', NULL, 1),
(7043090, 1069939, 81362, '<td valign="top">Selective focus works well here. Water drops lend a bejeweled effect.</td>', 'Selective focus works well here. Water drops lend a bejeweled effect.', '2013-05-25 17:30:58.000000', NULL, 1),
(7043091, 1069843, 81362, '<td valign="top">I''m enjoying the use of light here. Simplicity in colors too.</td>', 'I''m enjoying the use of light here. Simplicity in colors too.', '2013-05-25 17:31:56.000000', NULL, 1),
(7043092, 1069931, 81362, '<td valign="top">After seeing this, I want a snack. Can almost smell the fruit.</td>', 'After seeing this, I want a snack. Can almost smell the fruit.', '2013-05-25 17:33:30.000000', NULL, 1),
(7043093, 1069867, 81362, '<td valign="top">Find myself wanting the barbs in focus along with the background (might take a telephoto lens, tight aperture, and starting a little further back from the barrier).</td>', 'Find myself wanting the barbs in focus along with the background (might take a telephoto lens, tight aperture, and starting a little further back from the barrier).', '2013-05-25 17:37:07.000000', NULL, 1),
(7043094, 1069620, 81362, '<td valign="top">Cute, and sharp focus helps.</td>', 'Cute, and sharp focus helps.', '2013-05-25 17:38:00.000000', NULL, 1),
(7043095, 1069879, 81362, '<td valign="top">The light position gives the sense of a well crafted still life we could find among old master paintings in a museum.</td>', 'The light position gives the sense of a well crafted still life we could find among old master paintings in a museum.', '2013-05-25 17:40:52.000000', NULL, 1),
(7043096, 1069969, 81362, '<td valign="top">Could be used as a teaching illustration in a class about creatures hiding themselves in nature.</td>', 'Could be used as a teaching illustration in a class about creatures hiding themselves in nature.', '2013-05-25 17:41:38.000000', NULL, 1),
(7043097, 1069790, 28427, '<td valign="top">How delicate nature can be.  How beautiful and can be presented with a photograph.</td>', 'How delicate nature can be.  How beautiful and can be presented with a photograph.', '2013-05-25 17:42:41.000000', NULL, 1),
(7043098, 1069971, 81362, '<td valign="top">Almost metallic. Not very green, but more interesting than many of the competitors.</td>', 'Almost metallic. Not very green, but more interesting than many of the competitors.', '2013-05-25 17:43:05.000000', NULL, 1),
(7043099, 1069962, 81362, '<td valign="top">Bumping up a notch for originality.</td>', 'Bumping up a notch for originality.', '2013-05-25 17:43:57.000000', NULL, 1),
(7043100, 1069944, 81362, '<td valign="top">Reminds me of hand illustrated scientific specimen documentation from the time of early explorers.</td>', 'Reminds me of hand illustrated scientific specimen documentation from the time of early explorers.', '2013-05-25 17:44:44.000000', NULL, 1),
(7043101, 1069785, 81362, '<td valign="top">Glad you captured the complete reflection (sometimes harder than people think).</td>', 'Glad you captured the complete reflection (sometimes harder than people think).', '2013-05-25 17:45:55.000000', NULL, 1),
(7043102, 1069843, 28427, '<td valign="top">A precious caterpillar which will become a beautiful butterfly.  Nice how you''re showing how tiny she is on this big leaf.  Nice details and dof.</td>', 'A precious caterpillar which will become a beautiful butterfly.  Nice how you''re showing how tiny she is on this big leaf.  Nice details and dof.', '2013-05-25 17:53:16.000000', NULL, 1),
(7043150, 1069790, 80425, '<td valign="top">Like it. Very sharp.</td>', 'Like it. Very sharp.', '2013-05-25 23:59:33.000000', NULL, 1),
(7043162, 1069994, 119419, '<td valign="top">still in the emerald prison I see ;)</td>', 'still in the emerald prison I see ;)', '2013-05-26 00:54:02.000000', NULL, 1),
(7043199, 1069914, 108580, '<td valign="top">Wonderful lines and stark contrast of new growth vs winter browns. Puik</td>', 'Wonderful lines and stark contrast of new growth vs winter browns. Puik', '2013-05-26 05:57:51.000000', NULL, 1),
(7043201, 1069795, 28427, '<td valign="top">Looking at the reflection: if you rotate it to the left, the bum at its reflection becomes the head seen from on top and the nose and his right eye becomes the bum and 2 rear legs (sorry, just my imagination).<br/>I like the twinkles above the water surface.  They support the title of your work.  Very well done.</td>', 'Looking at the reflection: if you rotate it to the left, the bum at its reflection becomes the head seen from on top and the nose and his right eye becomes the bum and 2 rear legs (sorry, just my imagination).I like the twinkles above the water surface.  They support the title of your work.  Very well done.', '2013-05-26 06:05:34.000000', NULL, 1),
(7043208, 1069839, 108580, '<td valign="top">Wunderbar! Crisp, form, rules, techno. DMC</td>', 'Wunderbar! Crisp, form, rules, techno. DMC', '2013-05-26 06:40:11.000000', NULL, 1),
(7043249, 1069950, 118154, '<td valign="top">Certainly is,this looks like someone who I have admired before ?<br/>I would have cropped this a little tighter but its a real nice shot of a lovely looking lady.<br/>Hope it goes well.</td>', 'Certainly is,this looks like someone who I have admired before ?I would have cropped this a little tighter but its a real nice shot of a lovely looking lady.Hope it goes well.', '2013-05-26 12:53:11.000000', NULL, 1),
(7043250, 1069978, 118154, '<td valign="top">Yes a very mean look,nice image.</td>', 'Yes a very mean look,nice image.', '2013-05-26 12:54:58.000000', NULL, 1),
